From 3118484b8d66f2643c20e5df8bc9dfcbb73a2b2d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 16:44:40 +0100
Subject: [PATCH] wallpapers/image: Add a search field to the wallpaper picker

Finding an image in a large wallpaper collection meant scrolling through
the whole grid. Add a search field to the Images header that filters the
wallpapers by name or file name, ignoring case; Ctrl+F focuses it.

BUG: 520221
---
 .../contents/ui/ThumbnailsComponent.qml       | 34 ++++++++++++++++++-
 .../image/imagepackage/contents/ui/config.qml | 10 ++++--
 2 files changed, 41 insertions(+), 3 deletions(-)

diff --git a/wallpapers/image/imagepackage/contents/ui/ThumbnailsComponent.qml b/wallpapers/image/imagepackage/contents/ui/ThumbnailsComponent.qml
index 730686fd57..02544c7329 100644
--- a/wallpapers/image/imagepackage/contents/ui/ThumbnailsComponent.qml
+++ b/wallpapers/image/imagepackage/contents/ui/ThumbnailsComponent.qml
@@ -20,6 +20,7 @@ Item {

     property alias view: wallpapersGrid.view
     property var screenSize: Qt.size(Screen.width, Screen.height)
+    property string searchText


     readonly property QtObject imageModel: (configDialog.currentWallpaper === "org.kde.image") ? sortedWallpaperModel : imageWallpaper.slideFilterModel
@@ -30,6 +31,17 @@ Item {
         sortCaseSensitivity: Qt.CaseInsensitive
         sortColumn: 0
         sourceModel: (configDialog.currentWallpaper === "org.kde.image") ? imageWallpaper.wallpaperModel : null
+        filterRowCallback: (sourceRow, sourceParent) => {
+            const query = thumbnailsComponent.searchText.trim().toLocaleLowerCase();
+            if (query.length === 0) {
+                return true;
+            }
+            const index = sourceModel.index(sourceRow, 0, sourceParent);
+            const name = sourceModel.data(index, Qt.DisplayRole) ?? "";
+            const source = String(sourceModel.data(index, sourceModel.KItemModels.KRoleNames.role("source")));
+            const fileName = source.replace(/\/+$/, "").split("/").pop();
+            return name.toLocaleLowerCase().includes(query) || fileName.toLocaleLowerCase().includes(query);
+        }
         function indexOf(image : string) : int {
             if (!sourceModel) {
                 return -1
@@ -51,13 +63,22 @@ Item {
     }


+    onSearchTextChanged: {
+        // Updating the current index binding in the middle of the row removals
+        // leaves the grid showing the wrong wallpapers, so rebind it afterwards.
+        wallpapersGrid.view.currentIndex = -1;
+        sortedWallpaperModel.invalidateFilter();
+        wallpapersGrid.view.positionViewAtBeginning();
+        wallpapersGrid.resetCurrentIndex();
+    }
+
     Connections {
         target: imageWallpaper
         function onLoadingChanged(loading: bool) {
             if (loading) {
                 return;
             }
-            if (configDialog.currentWallpaper === "org.kde.image" && imageModel.indexOf(cfg_Image) < 0) {
+            if (configDialog.currentWallpaper === "org.kde.image" && imageWallpaper.wallpaperModel.indexOf(cfg_Image) < 0) {
                 imageWallpaper.addUsersWallpaper(cfg_Image);
             }
             wallpapersGrid.resetCurrentIndex();
@@ -67,6 +88,7 @@ Item {
     Connections {
         target: root
         function onWallpaperBrowseCompleted() {
+            thumbnailsComponent.searchText = "";
             // Scroll to top to view added images
             wallpapersGrid.view.positionViewAtIndex(0, GridView.Beginning);
             wallpapersGrid.resetCurrentIndex(); // BUG 455129
@@ -87,6 +109,16 @@ Item {
             Layout.fillWidth: true
             text: i18nd("plasma_wallpaper_org.kde.image", "Images")
             actions: [
+                Kirigami.Action {
+                    icon.name: "search-symbolic"
+                    text: i18ndc("plasma_wallpaper_org.kde.image", "@action:button", "Search")
+                    visible: configDialog.currentWallpaper == "org.kde.image"
+                    displayHint: Kirigami.DisplayHint.KeepVisible
+                    displayComponent: Kirigami.SearchField {
+                        text: thumbnailsComponent.searchText
+                        onTextChanged: thumbnailsComponent.searchText = text
+                    }
+                },
                 Kirigami.Action {
                     icon.name: "list-add-symbolic"
                     text: i18ndc("plasma_wallpaper_org.kde.image", "@action:button the thing being added is an image file", "Add…")
diff --git a/wallpapers/image/imagepackage/contents/ui/config.qml b/wallpapers/image/imagepackage/contents/ui/config.qml
index 533cc1fff8..990288a4ba 100644
--- a/wallpapers/image/imagepackage/contents/ui/config.qml
+++ b/wallpapers/image/imagepackage/contents/ui/config.qml
@@ -16,6 +16,7 @@ import org.kde.newstuff as NewStuff
 import org.kde.kcmutils as KCM
 import org.kde.kirigami as Kirigami
 import org.kde.config as KConfig
+import org.kde.kitemmodels as KItemModels

 /**
  * For proper alignment, an ancestor **MUST** have id "appearanceRoot" and property "parentLayout"
@@ -86,8 +87,13 @@ ColumnLayout {
         cfg_DynamicMode = mode;

         if (root.configDialog.currentWallpaper === "org.kde.image") {
-            selectWallpaper(thumbnailsLoader.item.view.currentItem.key,
-                            thumbnailsLoader.item.view.currentItem.selectors);
+            // The search can hide the current wallpaper, so look it up in the model instead of the view.
+            const model = imageWallpaper.wallpaperModel;
+            const index = model.index(model.indexOf(cfg_Image), 0);
+            if (index.valid) {
+                selectWallpaper(model.data(index, model.KItemModels.KRoleNames.role("source")),
+                                model.data(index, model.KItemModels.KRoleNames.role("selectors")));
+            }
         }
     }

